create extension if not exists pgcrypto;
create table if not exists players(id uuid primary key default gen_random_uuid(),display_name text not null unique,total_attempts integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists streak_attempts(id uuid primary key default gen_random_uuid(),player_id uuid not null references players(id) on delete cascade,score integer not null check(score>=0),total_time_ms integer not null check(total_time_ms>=0),average_time_ms integer not null check(average_time_ms>=0),failed_question_id text not null,created_at timestamptz not null default now());
create table if not exists player_best_scores(player_id uuid primary key references players(id) on delete cascade,best_score integer not null,best_average_time_ms integer not null,achieved_at timestamptz not null default now());
create or replace function record_streak_attempt(p_display_name text,p_score integer,p_total_time_ms integer,p_average_time_ms integer,p_failed_question_id text) returns void language plpgsql security definer as $$ declare pid uuid; begin insert into players(display_name,total_attempts) values(trim(p_display_name),1) on conflict(display_name) do update set total_attempts=players.total_attempts+1,updated_at=now() returning id into pid;insert into streak_attempts(player_id,score,total_time_ms,average_time_ms,failed_question_id) values(pid,p_score,p_total_time_ms,p_average_time_ms,p_failed_question_id);insert into player_best_scores(player_id,best_score,best_average_time_ms,achieved_at) values(pid,p_score,p_average_time_ms,now()) on conflict(player_id) do update set best_score=excluded.best_score,best_average_time_ms=excluded.best_average_time_ms,achieved_at=excluded.achieved_at where excluded.best_score>player_best_scores.best_score or(excluded.best_score=player_best_scores.best_score and excluded.best_average_time_ms<player_best_scores.best_average_time_ms);end $$;
create or replace view leaderboard_all as select p.display_name,b.best_score,p.total_attempts,b.best_average_time_ms,b.achieved_at from player_best_scores b join players p on p.id=b.player_id order by b.best_score desc,b.best_average_time_ms asc,b.achieved_at asc;
create or replace view leaderboard_top10 as select p.display_name,a.score as best_score,1 as total_attempts,a.average_time_ms as best_average_time_ms,a.created_at as achieved_at from streak_attempts a join players p on p.id=a.player_id order by a.score desc,a.average_time_ms asc,a.created_at asc limit 10;
